#!/usr/bin/env python3
"""Typed capture records and revision-aware publication reconciliation.

A record identity is ``(type, id)`` and is global across captures.  At a query
time only rows with ``published <= query`` exist; the highest visible revision
wins, identical semantic contents at that revision collapse to one record and
two or more distinct contents make the identity conflicted (never live).
"""
from common import (Invalid, MAX_ATTEMPT, MAX_PAYLOAD, MAX_REVISION, MAX_TIME,
                    address, decimal, decode64, ident)

